 	for (i = 0; i < rm->data.op_nents; i++) {
 		/* XXX will have to put_page for page refs */
 		if (!zcopy)
 			__free_page(sg_page(&rm->data.op_sg[i]));
 		else
 			put_page(sg_page(&rm->data.op_sg[i]));
 	}
 	rm->data.op_nents = 0;

