 	if (rm->rdma.op_rdma_mr)
 		kref_put(&rm->rdma.op_rdma_mr->r_kref, __rds_put_mr_final);

 	if (rm->atomic.op_active)
 		rds_atomic_free_op(&rm->atomic);
